// Pre-compute slug for every topic (derived from title)
function _slugify(title) {
  return title
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 80)
}

BLOG_TOPICS.forEach((t) => {
  if (!t.slug) t.slug = _slugify(t.title)
})
